async function finalBinding(expectedHead){
  const binding=await read(BINDING_FILE);if(binding.schemaVersion!==1||binding.state!=='FINAL_COMMITTED_BACKEND_SOURCE'||binding.sourceCommit!==expectedHead||!isHex(binding.sourceCommit)||!Array.isArray(binding.sourcePins)||binding.sourcePins.length!==1||!binding.sourcePins.every(validSourcePin)||!same(binding.sourcePins.map(p=>p.path),ALLOWED_DELTAS))throw Error('PENDING_FINAL_COMMITTED_BACKEND_SOURCE: real new HEAD, exact web raw pin, actual validation and new Node9 freeze must bind before capture/build');
  const {value:validation}=await exactExternalReference(binding.rootFunctionalValidation,{json:true});
  if(validation.schemaVersion!==1||!Array.isArray(validation.sourcePins)||validation.sourcePins.length!==1||!validation.sourcePins.every(validSourcePin)||!same(canonicalPins(validation.sourcePins),canonicalPins(binding.sourcePins))||validation.checks?.rustFocusedPassed!==true||validation.checks?.rustfmtPassed!==true||validation.checks?.nodeRegressionPassed!==true||!Array.isArray(validation.actualChecks)||validation.actualChecks.length!==3)throw Error('Actual functional validation must bind the exact web raw pin and all three successful checks');
  const expected={rustFocused:8,nodeRegression:210,rustfmt:1},seen=new Set();for(const check of validation.actualChecks){if(!check||!Object.hasOwn(expected,check.kind)||seen.has(check.kind)||!same(Object.keys(check).sort(),['exitCode','failed','kind','log','passed','receipt'])||check.exitCode!==0||check.failed!==0||check.passed!==expected[check.kind])throw Error('Functional actualChecks must contain exactly rustFocused8, nodeRegression210 and rustfmt1 actual passing results');seen.add(check.kind);await exactExternalReference(check.log);await exactExternalReference(check.receipt,{json:true});}
  const {value:driver}=await exactExternalReference(binding.driverFrozenManifest,{json:true});
  if(driver.schemaVersion!==1||driver.actualCodeCommit!==expectedHead||driver.driverSourceCommit!==expectedHead||!Array.isArray(driver.files)||driver.files.length!==9||!same(driver.files.map(p=>p.file).sort(),[...NODE_INPUTS].sort())||driver.files.some(p=>!Number.isSafeInteger(p.bytes)||p.bytes<=0||!isSha(p.sha256))||driver.sourceSha256!==sha(JSON.stringify(driver.files))||validation.driverSourceSha256!==driver.sourceSha256||!same(validation.driverSourcePins,driver.files))throw Error('Actual new committed Node9 freeze must match validation and cannot reuse db4e as current');
  return{binding,driver};
}

